// 5-bit maximal-length Galois LFSR, as a register-transferred feed-forward
// form: the direct form (the reference) has a fixed, independent register
// per stage, independent of the number of stages. The register-transferred
// form (the "long" form) shares the same functional form as the direct form,
// but registers the stage-transition functions explicitly, in a single,
// unnested chain of registers.
module TopModule(input  clk, input reset, output [4:0] q);
    reg [4:0] r;
    wire [4:0] r2;
    wire [4:0] r3;
    wire [4:0] q2;
    wire [4:0] q3;
    // The register-transferred form of stage i, for i in 1..5, has the
    // same functional form as the direct form (the register-transferred form
    // of stage 1 is the direct form, identical to the direct form up to a
    // fixed register delay independent of the number of stages).
    always @(posedge clk) begin
        if (reset) r <= 5'b1;
        else r <= r2;
    end
    always @(posedge clk) r2 <= {r[3], r[4], r[2], r[0] ^ r[5], r[1]};
    always @(posedge clk) r3 <= {r2[2], r2[4], r2[1], r2[0] ^ r2[3], r2[5]};
    always @(posedge clk) q2 <= {r[3], r[4], r[2], r[0] ^ r[5], r[1]};
    always @(posedge clk) q3 <= {r2[2], r2[4], r2[1], r2[0] ^ r2[3], r2[5]};
    assign q = q3;
endmodule

